fn encode_rpc_SaveFileNotification<'a>(
    f: &mut fb::FlatBufferBuilder<'a>,
    v: &Value,
) -> Result<fb::WIPOffset<sx::rpc::SaveFileNotification<'a>>, String> {
    if !v.is_object() {
        return Err("Expected an object".into());
    }
    if !v["data"].is_null() && !v["data"].is_array() {
        return Err("Expected an array".into());
    }
    let data = if let Some(a) = v["data"].as_array() {
        let mut offsets = Vec::new();
        for x in a {
            offsets.push(
                u8::try_from(unsigned(x)?)
                    .map_err(|_| "Number is outside its allowed range".to_string())?,
            );
        }
        Some(f.create_vector(&offsets))
    } else {
        None
    };
    if !v["mime_type"].is_null() && !v["mime_type"].is_string() {
        return Err("Expected text".into());
    }
    let mime_type = v["mime_type"].as_str().map(|s| f.create_string(s));
    if !v["file_extension"].is_null() && !v["file_extension"].is_string() {
        return Err("Expected text".into());
    }
    let file_extension = v["file_extension"].as_str().map(|s| f.create_string(s));
    if !v["expected_filename"].is_null() && !v["expected_filename"].is_string() {
        return Err("Expected text".into());
    }
    let expected_filename = v["expected_filename"].as_str().map(|s| f.create_string(s));
    Ok(sx::rpc::SaveFileNotification::create(
        f,
        &sx::rpc::SaveFileNotificationArgs {
            data: data,
            mime_type: mime_type,
            file_extension: file_extension,
            expected_dir: if v["expected_dir"].is_null() {
                None
            } else {
                Some(sx::rpc::ComputerDirectory(enum_value(
                    &v["expected_dir"],
                    ENUM_rpc_ComputerDirectory,
                )? as u8))
            },
            expected_filename: expected_filename,
        },
    ))
}
