pub fn encode_rpc(name: &str, value: &Value, tx: u32) -> Result<Vec<u8>, String> {
    let mut f = fb::FlatBufferBuilder::new();
    let (kind, body) = encode_rpc_RpcMessage(&mut f, &json!({"type":name,"value":value}))?;
    let tx = sx::datatypes::TransactionId::new(tx);
    let header = sx::rpc::RpcMessageHeader::create(
        &mut f,
        &sx::rpc::RpcMessageHeaderArgs {
            tx_id: Some(&tx),
            message_type: kind,
            message: Some(body),
        },
    );
    let headers = f.create_vector(&[header]);
    let bundle = sx::MessageBundle::create(
        &mut f,
        &sx::MessageBundleArgs {
            rpc_msgs: Some(headers),
            ..Default::default()
        },
    );
    f.finish(bundle, None);
    Ok(f.finished_data().to_vec())
}
pub fn encode_rpc_batch(requests: &[(String, Value)], tx: u32) -> Result<Vec<u8>, String> {
    if requests.len() > 128 {
        return Err("Too many operations".into());
    }
    let mut f = fb::FlatBufferBuilder::new();
    let mut headers = Vec::new();
    for (name, value) in requests {
        let (kind, body) = encode_rpc_RpcMessage(&mut f, &json!({"type":name,"value":value}))?;
        let id = sx::datatypes::TransactionId::new(tx);
        headers.push(sx::rpc::RpcMessageHeader::create(
            &mut f,
            &sx::rpc::RpcMessageHeaderArgs {
                tx_id: Some(&id),
                message_type: kind,
                message: Some(body),
            },
        ));
    }
    let headers = f.create_vector(&headers);
    let bundle = sx::MessageBundle::create(
        &mut f,
        &sx::MessageBundleArgs {
            rpc_msgs: Some(headers),
            ..Default::default()
        },
    );
    f.finish(bundle, None);
    Ok(f.finished_data().to_vec())
}
pub fn decode_rpc(bytes: &[u8]) -> Result<Vec<(String, u32, Value)>, String> {
    let bundle = fb::root::<sx::MessageBundle>(bytes).map_err(|e| e.to_string())?;
    decode_rpc_verified(bundle)
}
pub fn decode_rpc_verified(bundle: sx::MessageBundle) -> Result<Vec<(String, u32, Value)>, String> {
    let mut out = Vec::new();
    if let Some(headers) = bundle.rpc_msgs() {
        for header in headers {
            let v = decode_rpc_RpcMessageHeader(header);
            if let Some(name) = v["message"]["type"].as_str() {
                out.push((
                    name.to_owned(),
                    header.tx_id().map(|t| t.id()).unwrap_or(0),
                    v["message"]["value"].clone(),
                ));
            }
        }
    }
    Ok(out)
}
pub fn encode_pubsub(value: &Value) -> Result<Vec<u8>, String> {
    let mut f = fb::FlatBufferBuilder::new();
    let h = encode_pub_sub_PubSubHeader(&mut f, value)?;
    let headers = f.create_vector(&[h]);
    let bundle = sx::MessageBundle::create(
        &mut f,
        &sx::MessageBundleArgs {
            pub_sub_msgs: Some(headers),
            ..Default::default()
        },
    );
    f.finish(bundle, None);
    Ok(f.finished_data().to_vec())
}
pub fn decode_pubsub(bytes: &[u8]) -> Result<Vec<Value>, String> {
    let bundle = fb::root::<sx::MessageBundle>(bytes).map_err(|e| e.to_string())?;
    decode_pubsub_verified(bundle)
}
pub fn decode_pubsub_verified(bundle: sx::MessageBundle) -> Result<Vec<Value>, String> {
    Ok(bundle
        .pub_sub_msgs()
        .map(|h| h.iter().map(decode_pub_sub_PubSubHeader).collect())
        .unwrap_or_default())
}
